  /**
   * Find out registered numbered annotations not existing in sups any more, then ask for sync which may remove .
   */
  removeNumberedAnnotationsNotInSuperScripts() {
    const numbersofSups = this.findAllSupsWithNumber();
    if (this.poem?.numberedAnnotationBriefs && this.poem?.numberedAnnotationBriefs?.length > 0) {
      let candidatesToRemove = [];
      for (const b of this.poem.numberedAnnotationBriefs) {
        if (numbersofSups.indexOf(b.orderNumber) < 0) {
          candidatesToRemove.push(b);
        }
      }
      if (candidatesToRemove.length > 0) {
        const numberList = candidatesToRemove.map((d) => d.orderNumber).join(", ");
        this.confirmService.open($localize`Confirm`, $localize`There are some registered numbered annotations not existing in poem anymore: ${numberList}. Do you want to remove them?`).subscribe((r) => {
          if (r) {
            for (const b of candidatesToRemove) {
              this.numberedAnnotationsService.delete(b.id).subscribe({
                next: (ok) => {
                  if (ok) {
                    const idx = this.poem.numberedAnnotationBriefs?.findIndex((d) => d.id === b.id);
                    if (idx !== void 0 && idx >= 0) {
                      this.poem.numberedAnnotationBriefs?.splice(idx, 1);
                      this.ref.detectChanges();
                    }
                  }
                },
                error: (error) => this.alertService.error(error)
              });
            }
          }
        });
      } else {
        this.alertService.info($localize`No orphaned annotations found.`);
      }
    } else {
      this.alertService.warn($localize`No numbered annotation found.`);
    }
  }
  /**
   * All subs like [123], and return a list of 123.
   */
  findAllSupsWithNumber() {
    if (this.poemForm.controls.bodyType.value === Fonlow_PoemsApp_Data_Client.BodyType.HTML) {
      if (!this.poemForm.controls.body.value) {
        return [];
      }
      const htmlTemplate = HtmlFunc.htmlToDivElement(this.poemForm.controls.body.value);
      const sups = htmlTemplate.getElementsByTagName("sup");
      let supNumbers = [];
      for (let i = 0; i < sups.length; i++) {
        const supText = sups[i].innerText;
        const regex = /\[(?<num>\d+)\]/g;
        const match = regex.exec(supText);
        const numText = match?.groups?.num;
        if (numText != void 0) {
          supNumbers.push(numText);
        }
      }
      return supNumbers.map((d) => parseInt(d));
    }
    return [];
  }
  insertNewSup() {
    var sups = this.findAllSupsWithNumber();
    var max = sups.length > 0 ? Math.max.apply(Math, sups) : 0;
    console.debug(JSON.stringify(sups));
    const next = max + 1;
    this.htmlEditor.focus();
    this.htmlEditorService.restoreSelection();
    this.htmlEditorService.insertHtml(`<sup class="num">[${next}]</sup>`);
  }
  ReorderAllSupsWithNumber() {
    if (this.poemForm.controls.bodyType.value === Fonlow_PoemsApp_Data_Client.BodyType.HTML) {
      const htmlTemplate = HtmlFunc.htmlToDivElement(this.poemForm.controls.body.value);
      const sups = htmlTemplate.getElementsByTagName("sup");
      if (sups.length !== this.poem.numberedAnnotationBriefs?.length) {
        this.alertService.warn($localize`Reordering is supported only when the number of superscripts equals to the number of numbered annotations.`);
        return;
      }
      const supsWithNumber = [];
      for (let i = 0; i < sups.length; i++) {
        const supText = sups[i].innerText;
        const regex = /\[(?<num>\d+)\]/g;
        const match = regex.exec(supText);
        const numText = match?.groups?.num;
        if (numText != void 0) {
          supsWithNumber.push(sups[i]);
        }
      }
      let idAndOrderList = [];
      let supToChangeDic = {};
      for (let i = 0; i < supsWithNumber.length; i++) {
        const sup = supsWithNumber[i];
        const registereFound = this.poem.numberedAnnotationBriefs?.find((d) => "[" + d.orderNumber.toString() + "]" === sup.innerText);
        const newOrderNumber = i + 1;
        if (registereFound) {
          if (registereFound.orderNumber !== newOrderNumber) {
            idAndOrderList.push({ item1: registereFound.id, item2: newOrderNumber });
            supToChangeDic[registereFound.id] = sup;
          }
        } else {
          this.alertService.warn($localize`Superscript with ${sup.innerText} is not matching any numbered annotations. Please Suggest Numbered Annotations and Remove Orphaned Annotations.`);
          return;
        }
      }
      if (idAndOrderList.length > 0) {
        this.numberedAnnotationsService.bulkUpdateOrderNumbers(idAndOrderList).subscribe(() => {
          for (let pk of idAndOrderList) {
            const registeredFound = this.poem.numberedAnnotationBriefs?.find((d) => d.id === pk.item1);
            if (registeredFound) {
              registeredFound.orderNumber = pk.item2;
            }
          }
          for (let d in supToChangeDic) {
            const sup = supToChangeDic[d];
            const g = idAndOrderList.find((k) => k.item1 === d);
            sup.innerText = "[" + g?.item2.toString() + "]";
          }
          this.poemForm.controls.body.setValue(htmlTemplate.innerHTML);
          this.poemForm.markAsDirty();
          this.poem.numberedAnnotationBriefs?.sort((a, b) => a.orderNumber - b.orderNumber);
          this.alertService.success($localize`Total number of changes: ${idAndOrderList.length}.`);
          this.saveAndOptionallyClose(false);
        });
      } else {
        this.alertService.info($localize`No need to reorder.`);
      }
    }
  }
